import { mkdirP, rmRF, which } from '@actions/io'
import { writeFile } from 'node:fs/promises'
import path, { join } from 'node:path'
import { info } from '@actions/core'
import { exec, ExecOptions } from '@actions/exec'
import { cwd } from 'node:process'
import { buildDirectory, relativePath, workspacePath } from './utils'

export type DockerComposeConfig = {
    mariaDbVersion: string
    phpVersion: string
    composerAuth: string
    opensearchVersion?: string
    magentoImage?: string
    extraConfigFiles?: string[]
}

export interface DockerExecOptions extends ExecOptions {
    user?: string
}

export function createConfig(
    mariaDbVersion: string,
    phpVersion: string,
    composerAuth: string,
    opensearchVersion: string,
    magentoImage: string,
    extraConfigFiles: string[],
): DockerComposeConfig {
    const options: DockerComposeConfig = {
        mariaDbVersion,
        phpVersion,
        composerAuth,
    }

    if (magentoImage) {
        options.magentoImage = magentoImage
    }

    if (opensearchVersion) {
        options.opensearchVersion = opensearchVersion
    }

    if (extraConfigFiles.length > 0) {
        options.extraConfigFiles = extraConfigFiles
    }

    return options
}

export class DockerCompose {
    private dockerPath?: string
    public readonly path: string

    constructor(
        public readonly config: DockerComposeConfig,
        private name: string,
    ) {
        this.path = buildDirectory(this.name)
    }

    async up(): Promise<void> {
        await mkdirP(this.path)
        await this.generateComposeConfig()
        const result = await this.dockerComposeCommand('up', ['-d', '--wait'])
        if (result !== 0) {
            throw new Error(`Failed to start Docker Compose in ${this.path} directory`)
        }
        info(`Started Docker Compose in ${this.path} directory`)
    }

    async stop(container: string): Promise<void> {
        await this.dockerComposeCommand('stop', [container])
    }

    async down(): Promise<void> {
        await this.dockerComposeCommand('down', ['-v'])
        await rmRF(this.path)
        info(`Stopped Docker Compose in ${this.path} directory and cleaned up data`)
    }

    async exec(container: string, command: string, args: string[], options?: DockerExecOptions) {
        const userArgs = options?.user ? ['-u', options.user] : []

        if (options) {
            delete options.user
        }

        const result = await this.dockerComposeCommand('exec', [...userArgs, container, command, ...args], options)

        if (result > 0) {
            throw new Error(`Failed to execute command ${command} in container ${container}`)
        }

        return true
    }

    async execLines(container: string, command: string, args: string[]): Promise<string[]> {
        const lines: string[] = []

        await this.exec(container, command, args, { listeners: { stdline: (line) => lines.push(line) } })

        return lines
    }

    async binding(container: string, port: number): Promise<string | boolean> {
        let binding = ''
        const exitCode = await this.dockerComposeCommand('port', [container, port.toString()], {
            listeners: {
                stdline: (line) => (binding = line),
            },
        })

        if (exitCode === 0) {
            return binding
        }
        return false
    }

    async copyFrom(container: string, containerDirectory: string, localDirectory: string) {
        const relativeLocalDirectory = relativePath(workspacePath(localDirectory), this.path)

        info(`Copying ${containerDirectory} from ${container} container into ${relativeLocalDirectory}`)

        const exitCode = await this.dockerComposeCommand('cp', [
            `${container}:${containerDirectory}`,
            relativeLocalDirectory,
        ])

        return exitCode === 0
    }

    async copyTo(container: string, localDirectory: string, containerDirectory: string) {
        const relativeLocalDirectory = relativePath(workspacePath(localDirectory), this.path)

        info(`Copying ${relativeLocalDirectory} into ${container} container ${containerDirectory}`)

        const exitCode = await this.dockerComposeCommand('cp', [
            relativeLocalDirectory,
            `${container}:${containerDirectory}`,
        ])

        return exitCode === 0
    }

    private async generateComposeConfig(): Promise<void> {
        await writeFile(join(this.path, 'docker-compose.yml'), JSON.stringify(this.composeConfig(), null, 2))
    }

    composeConfig(): any {
        const config = { services: {} }
        this.dbContainerConfig(config)
        this.magentoContainerConfig(config)
        this.opensearchContainerConfig(config)
        return config
    }

    private dbContainerConfig(config: any): void {
        config.services.db = {
            command: [
                'mariadbd',
                '--max_allowed_packet=1024M',
                '--explicit_defaults_for_timestamp=on',
                '--character_set_server=utf8mb4',
                '--collation-server=utf8mb4_unicode_520_ci',
            ],
            environment: {
                MYSQL_DATABASE: 'magento',
                MYSQL_PASSWORD: 'magento',
                MYSQL_ROOT_PASSWORD: 'magento',
                MYSQL_USER: 'magento',
            },
            healthcheck: {
                test: ['CMD', 'healthcheck.sh', '--connect', '--innodb_initialized'],
                interval: '10s',
                timeout: '5s',
                retries: '5',
            },
            image: `ghcr.io/wardenenv/mariadb:${this.config.mariaDbVersion}`,
        }
    }

    private magentoContainerConfig(config: any): void {
        const magentoImage = (this.config.magentoImage ?? `ghcr.io/wardenenv/php-fpm:%PHP_VERSION%-magento2`).replace(
            '%PHP_VERSION%',
            this.config.phpVersion,
        )

        config.services.magento = {
            image: magentoImage,
            depends_on: {
                db: {
                    condition: 'service_started',
                    required: true,
                },
            },
            environment: {
                COMPOSER_MEMORY_LIMIT: '-1',
                // Disable security blocking for Composer as we might install older Magento versions
                COMPOSER_NO_SECURITY_BLOCKING: '1',
                // Disable security audit for Composer as we might install older Magento versions
                COMPOSER_NO_AUDIT: '1',
                COMPOSER_VERSION: '2',
                COMPOSER_AUTH: this.config.composerAuth,
                MAGE_DEBUG_SHOW_ARGS: '1',
                TRAEFIK_DOMAIN: 'magento.test',
                TRAEFIK_SUBDOMAIN: '',
                NODE_VERSION: '24',
            },
        }
    }

    private opensearchContainerConfig(config: any): void {
        if (!this.config.opensearchVersion) {
            return
        }

        config.services.opensearch = {
            environment: {
                DISABLE_SECURITY_PLUGIN: 'true',
                OPENSEARCH_JAVA_OPTS: '-Xms64m -Xmx512m',
                'discovery.type': 'single-node',
            },
            ports: ['9200'],
            image: `ghcr.io/wardenenv/opensearch:${this.config.opensearchVersion}`,
            volumes: ['opensearch:/usr/share/opensearch/data'],
        }
        config.volumes ??= {}
        config.volumes.opensearch = {}
    }

    private async dockerCommand(args: string[], execOptions?: ExecOptions): Promise<number> {
        if (!this.dockerPath) {
            this.dockerPath = await which('docker')
        }

        return await exec(
            this.dockerPath,
            args,
            Object.assign(execOptions || {}, {
                cwd: path.relative(cwd(), this.path),
            }),
        )
    }

    private async dockerComposeCommand(command: string, args: string[], execOptions?: ExecOptions): Promise<number> {
        const dockerConfigArgs: string[] = []
        if (this.config.extraConfigFiles) {
            dockerConfigArgs.push('-f', './docker-compose.yml')
            for (const extraConfigFile of this.config.extraConfigFiles) {
                const configPath = relativePath(workspacePath(extraConfigFile), this.path)
                dockerConfigArgs.push('-f', configPath)
            }
        }
        return this.dockerCommand(['compose', ...dockerConfigArgs, command, ...args], execOptions)
    }
}
